private void sendCredits(){
  try {
    String recipientAddress=Helper.getValue(inputSendAddress.getText());
    String amountString=Helper.getValue(inputSendAmount.getText());
    String amount=new DecimalFormat(Helper.SDK_AMOUNT_FORMAT,new DecimalFormatSymbols(Locale.US)).format(new BigDecimal(amountString).doubleValue());
    disableSendControls();
    WalletSendTask task=new WalletSendTask(recipientAddress,amount,walletSendProgress,new WalletSendTask.WalletSendHandler(){
      @Override public void onSuccess(){
        double sentAmount=Double.valueOf(amount);
        String message=getResources().getQuantityString(R.plurals.you_sent_credits,sentAmount == 1.0 ? 1 : 2,new DecimalFormat("#,###.##").format(sentAmount));
        Snackbar.make(getView(),message,Snackbar.LENGTH_LONG).show();
        inputSendAddress.setText(null);
        inputSendAmount.setText(null);
        enableSendControls();
      }
      @Override public void onError(Exception error){
        Snackbar.make(getView(),R.string.send_credit_error,Snackbar.LENGTH_LONG).setBackgroundTint(Color.RED).setTextColor(Color.WHITE).show();
        enableSendControls();
      }
    });
    task.executeOnExecutor(AsyncTask.THREAD_POOL_EXECUTOR);
  } catch (NumberFormatException e) {
    Snackbar.make(getView(), R.string.invalid_amount_format, Snackbar.LENGTH_LONG).setBackgroundTint(Color.RED).setTextColor(Color.WHITE).show();
    enableSendControls();
  }
}
